package com.firebrowse.lite;
import android.app.*;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import android.graphics.Color;import android.content.*;import android.net.Uri;
public class MainActivity extends Activity {
 LinearLayout root,bar; EditText address; WebView web; String home="file:///android_asset/home.html";
 TextView button(String name,Runnable action){TextView t=new TextView(this);t.setText(name);t.setTextSize(18);t.setTextColor(-1);t.setPadding(16,14,16,14);t.setBackgroundColor(Color.rgb(125,72,133));t.setFocusable(true);t.setOnClickListener(v->action.run());return t;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(1024,1024);root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(Color.rgb(39,25,51));setContentView(root);bar=new LinearLayout(this);root.addView(bar);bar.addView(button("‹",()->{if(web.canGoBack())web.goBack();}));bar.addView(button("⌂",()->web.loadUrl(home)));address=new EditText(this);address.setSingleLine(true);address.setTextColor(-1);address.setHintTextColor(0xffcccccc);address.setHint("Adresse ou recherche");bar.addView(address,new LinearLayout.LayoutParams(0,-2,1));address.setOnEditorActionListener((v,a,e)->{go();return true;});bar.addView(button("GO",()->go()));bar.addView(button("☰",()->menu()));web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,String url){return intercept(url);}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest req){return intercept(req.getUrl().toString());}@Override public void onPageFinished(WebView w,String url){address.setText(url.equals(home)?"":url);}});web.setWebChromeClient(new WebChromeClient());web.loadUrl(home);}
 boolean intercept(String u){if(u.startsWith("firebrowse://")){String q=Uri.parse(u).getQueryParameter("q");if(q!=null){address.setText(q);go();}return true;}if(!(u.startsWith("https://")||u.startsWith("http://")||u.equals(home))){Toast.makeText(this,"Lien non pris en charge",0).show();return true;}return false;}
 void go(){String q=address.getText().toString().trim();if(q.isEmpty())return;if(!q.matches("(?i)^https?://.*"))q=(q.contains(".")&&!q.contains(" "))?"https://"+q:"https://www.google.com/search?q="+Uri.encode(q);web.loadUrl(q);}
 void menu(){String[] items={"Accueil","Recharger","Zoom +","Zoom -","Ajouter aux favoris","Favoris","Effacer les données de navigation"};new AlertDialog.Builder(this).setTitle("FireBrowse Cozy TV").setItems(items,(d,n)->{switch(n){case 0:web.loadUrl(home);break;case 1:web.reload();break;case 2:web.zoomIn();break;case 3:web.zoomOut();break;case 4:String u=web.getUrl();if(u!=null&&u.startsWith("http"))getPreferences(0).edit().putString("fav:"+u,u).apply();break;case 5:java.util.ArrayList<String> f=new java.util.ArrayList<>();for(String k:getPreferences(0).getAll().keySet())if(k.startsWith("fav:"))f.add(k.substring(4));new AlertDialog.Builder(this).setTitle("Favoris").setItems(f.toArray(new String[0]),(a,i)->web.loadUrl(f.get(i))).show();break;case 6:web.clearHistory();web.clearCache(true);CookieManager.getInstance().removeAllCookies(null);WebStorage.getInstance().deleteAllData();break;}}).show();}
 @Override public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_MENU){menu();return true;}return super.onKeyDown(key,event);}
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}